export default function next({ records, previous }) {
  const i = (previous?.i ?? -1) + 1,
    r = records[i];
  if (r && (!r.id || !r.fields?.Title || !r.fields?.Image?.[0]?.url))
    throw Error("Record missing ID, title or image");
  return {
    state: { i },
    more: !!r,
    id: r?.id ?? "",
    title: r?.fields?.Title ?? "",
    url: r?.fields?.Image?.[0]?.url ?? "",
  };
}

