export default function prepare({ title, url }) {
  if (!/^https:\/\//.test(url)) throw Error("Image URL must be HTTPS");
  return {
    input: [
      {
        role: "user",
        content: [
          {
            type: "input_text",
            text:
              "Describe the " +
              title +
              " including model, materials, color and condition. Leave unknown attributes blank.",
          },
          { type: "input_image", image_url: url },
        ],
      },
    ],
  };
}

