export default function description({ response }) {
  const text = (response?.output ?? [])
    .flatMap((x) => x.content ?? [])
    .filter((x) => x.type === "output_text")
    .map((x) => x.text)
    .join("\n");
  if (!text.trim()) throw Error("Empty image analysis");
  return { text };
}

