export default async function reserve({ id, analysis }, ctx) {
  try {
    analysis = JSON.parse(analysis);
  } catch {
    throw Error("Invalid analysis JSON");
  }
  const key = "inventory:" + id,
    s = await ctx.state.get(key);
  if (s?.status === "pending") throw Error("Inspect Airtable before retry");
  if (s?.status === "done") return { key, skip: true, records: [{ id, fields: {} }] };
  if (
    !analysis ||
    !["title", "description", "model", "material", "color", "condition"].every(
      (k) => typeof analysis[k] === "string",
    )
  )
    throw Error("Invalid analysis");
  await ctx.state.set(key, { status: "pending" });
  return {
    key,
    skip: false,
    records: [
      {
        id,
        fields: {
          Title: analysis.title,
          Description: analysis.description,
          Model: analysis.model,
          Material: analysis.material,
          Color: analysis.color,
          Condition: analysis.condition,
          AI_status: true,
        },
      },
    ],
  };
}

