export default async function confirm({ key, records, id }, ctx) {
  if (!Array.isArray(records) || records.length !== 1 || records[0].id !== id)
    throw Error("Unknown Airtable update outcome");
  await ctx.state.set(key, { status: "done" });
  return { ok: true };
}

