export default function ({ url }) {
  if (!/^https:\/\//.test(url)) throw Error("Expected HTTPS image URL");
  return {
    url:
      "https://serpapi.com/search.json?engine=google_reverse_image&image_url=" +
      encodeURIComponent(url),
  };
}

